def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"Expected integer, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"Number must be between 1 and 3999, got {n}")

    vals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    result = []
    for value, numeral in vals:
        count, n = divmod(n, value)
        result.append(numeral * count)
    return ''.join(result)


def from_roman(s):
    """Convert a Roman numeral string to an integer."""
    if not isinstance(s, str):
        raise ValueError(f"Expected string, got {type(s).__name__}")
    if not s:
        raise ValueError("Empty string")

    roman_vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Validate characters
    for ch in s:
        if ch not in roman_vals:
            raise ValueError(f"Invalid character: {ch!r}")

    # Validate well-formedness by round-tripping
    if to_roman(from_roman_validated(s)) != from_roman_simple(s):
        raise ValueError(f"Not a valid Roman numeral: {s!r}")

    return from_roman_simple(s)


def from_roman_simple(s):
    """Parse a Roman numeral assuming it is valid."""
    roman_vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        val = roman_vals[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total


def from_roman_validated(s):
    """Check that a numeral is well-formed by verifying it matches the canonical form."""
    return to_roman(from_roman_simple(s)) == _canonical_form(s)


def _canonical_form(s):
    """Return True if s is already in canonical (standard subtractive) form."""
    roman_vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Check no more than 3 consecutive same symbols
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
            if count > 3:
                return False
        else:
            count = 1

    # Check subtractive pairs are valid
    valid_subtractive = {('I', 'V'), ('I', 'X'), ('X', 'L'), ('X', 'C'), ('C', 'D'), ('C', 'M')}
    for i in range(len(s) - 1):
        curr_val = roman_vals[s[i]]
        next_val = roman_vals[s[i + 1]]
        if curr_val < next_val:
            if (s[i], s[i + 1]) not in valid_subtractive:
                return False

    # Check that repeated symbols follow correct ordering rules
    # V, L, D cannot repeat
    for ch in ['V', 'L', 'D']:
        if s.count(ch) > 1:
            return False

    # I can only precede V and X
    # X can only precede L and C
    # C can only precede D and M
    for i in range(len(s) - 1):
        curr_val = roman_vals[s[i]]
        next_val = roman_vals[s[i + 1]]
        if curr_val >= next_val:
            continue
        # curr < next, so this is a subtractive pair
        # The smaller symbol can only appear once before the larger
        if s[i] == 'I' and s[i + 1] not in ('V', 'X'):
            return False
        if s[i] == 'X' and s[i + 1] not in ('L', 'C'):
            return False
        if s[i] == 'C' and s[i + 1] not in ('D', 'M'):
            return False

    # Verify that the "from_roman" parse of this string produces something
    # whose canonical form is itself. This catches things like IIV, IXI, etc.
    parsed = from_roman_simple(s)
    if parsed < 1 or parsed > 3999:
        return False
    return to_roman(parsed) == s

def to_roman(n):
    """Convert an integer 1..3999 to a Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"Expected integer, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"Number must be between 1 and 3999, got {n}")

    vals = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    result = []
    for value, numeral in vals:
