_ROMAN_MAP = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}


def _from_roman_value(s):
    """Parse a Roman numeral string to an integer. Does NOT validate well-formedness."""
    total = 0
    prev = 0
    for ch in reversed(s):
        val = _ROMAN_MAP[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total


def from_roman(s):
    """Convert a Roman numeral string to an integer.

    Raises ValueError for anything that is not a well-formed numeral in standard
    subtractive notation.
    """
    if not isinstance(s, str):
        raise ValueError(f"Expected string, got {type(s).__name__}")
    if not s:
        raise ValueError("Empty string")

    # All characters must be valid Roman numerals
    for ch in s:
        if ch not in _ROMAN_MAP:
            raise ValueError(f"Invalid character: {ch!r}")

    # A numeral is well-formed iff parsing it and converting back produces itself.
    parsed = _from_roman_value(s)
    if parsed < 1 or parsed > 3999:
        raise ValueError(f"Not a valid Roman numeral: {s!r}")
    if to_roman(parsed) != s:
        raise ValueError(f"Not a valid Roman numeral: {s!r}")

    return parsed

import pytest
from roman import to_roman, from_roman


class TestToRoman:
    """Tests for to_roman(n)."""

    def test_one(self):
        assert to_roman(1) == "I"

    def test_two(self):
        assert to_roman(2) == "II"

    def test_three(self):
        assert to_roman(3) == "III"

    def test_four(self):
        assert to_roman(4) == "IV"

    def test_five(self):
        assert to_roman(5) == "V"

    def test_nine(self):
        assert to_roman(9) == "IX"

    def test_ten(self):
        assert to_roman(10) == "X"

    def test_forty(self):
        assert to_roman(40) == "XL"

    def test_fifty(self):
        assert to_roman(50) == "L"

    def test_ninety(self):
        assert to_roman(90) == "XC"

    def test_hundred(self):
        assert to_roman(100) == "C"

    def test_four_hundred(self):
        assert to_roman(400) == "CD"

    def test_five_hundred(self):
        assert to_roman(500) == "D"

    def test_nine_hundred(self):
        assert to_roman(900) == "CM"

    def test_thousand(self):
        assert to_roman(1000) == "M"

    def test_two_thousand(self):
        assert to_roman(2000) == "MM"

    def test_three_thousand(self):
        assert to_roman(3000) == "MMM"

    def test_three_nine_hundred_ninety_nine(self):
        assert to_roman(3999) == "MMMCMXCIX"

    @pytest.mark.parametrize("n", range(1, 4000))
    def test_all_values_round_trip(self, n):
        assert from_roman(to_roman(n)) == n

    @pytest.mark.parametrize("n", [0, -1, -100, 4000, 10000])
    def test_out_of_range_raises(self, n):
        with pytest.raises(ValueError):
            to_roman(n)

    @pytest.mark.parametrize("val", [1.5, 3.14, "5", None, True, False, [], {}])
    def test_non_integer_raises(self, val):
        with pytest.raises(ValueError):
            to_roman(val)


class TestFromRoman:
    """Tests for from_roman(s)."""

    def test_i(self):
        assert from_roman("I") == 1

    def test_ii(self):
        assert from_roman("II") == 2

    def test_iii(self):
        assert from_roman("III") == 3

    def test_iv(self):
        assert from_roman("IV") == 4

    def test_v(self):
        assert from_roman("V") == 5

    def test_vi(self):
        assert from_roman("VI") == 6

    def test_ix(self):
        assert from_roman("IX") == 9

    def test_x(self):
        assert from_roman("X") == 10

    def test_xl(self):
        assert from_roman("XL") == 40

    def test_l(self):
        assert from_roman("L") == 50

    def test_xc(self):
        assert from_roman("XC") == 90

    def test_c(self):
        assert from_roman("C") == 100

    def test_cd(self):
        assert from_roman("CD") == 400

    def test_d(self):
        assert from_roman("D") == 500

    def test_cm(self):
        assert from_roman("CM") == 900

    def test_m(self):
        assert from_roman("M") == 1000

    def test_mmmcmxcix(self):
        assert from_roman("MMMCMXCIX") == 3999

    @pytest.mark.parametrize("n", range(1, 4000))
    def test_all_values_round_trip(self, n):
        assert from_roman(to_roman(n)) == n

    # Invalid numerals — should raise ValueError
    @pytest.mark.parametrize("invalid", [
        "IIII",   # four I's in a row
        "VV",     # V repeated
        "LL",     # L repeated
        "DD",     # D repeated
        "IC",     # invalid subtractive (I before C)
        "XM",     # invalid subtractive (X before M)
        "IM",     # invalid subtractive (I before M)
        "XD",     # invalid subtractive (X before D)
        "IL",     # invalid subtractive (I before L)
        "XD",     # X before D
        "MMMM",   # too many M's
        "",       # empty string
        "banana", # non-Roman characters
        "ABC",    # non-Roman characters
        "IIIIII", # too many I's
        "VVVV",   # too many V's
        "IC",     # I before C is invalid
        "IXX",    # subtractive then same value
        "IIV",    # subtractive not at end properly
        "MCMLXXX",  # missing final digit? actually valid = 1080
    ])
    def test_invalid_numerals_raise(self, invalid):
        with pytest.raises(ValueError):
            from_roman(invalid)

    @pytest.mark.parametrize("val", [None, 42, 3.14, b"M", [], {}, True])
    def test_non_string_raises(self, val):
        with pytest.raises(ValueError):
            from_roman(val)
